INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7fca0786-62cd-40f5-bdb5-ef6c0ddd152b', 'a1b2c3d4-2222-4000-8000-000000000002', 3, 'Oração Mental', 'O silêncio que transforma', '{"intro": "A ora\u00e7\u00e3o mental \u00e9 a conversa \u00edntima da alma com Deus \u2014 sem f\u00f3rmulas, sem textos decorados. \u00c9 o cora\u00e7\u00e3o que fala ao Cora\u00e7\u00e3o. Santa Teresa de Jesus dizia que muitos abandonam a ora\u00e7\u00e3o mental por acharem que n\u00e3o sabem fazer \u2014 mas basta \"olhar para Ele que nos olha\". A ora\u00e7\u00e3o mental n\u00e3o exige erudi\u00e7\u00e3o; exige humildade e desejo. Mesmo 5 minutos de ora\u00e7\u00e3o mental valem mais que horas de distra\u00e7\u00e3o.", "prayer": "Jesus manso e humilde de cora\u00e7\u00e3o, fazei o meu cora\u00e7\u00e3o semelhante ao Vosso. Ensina-me o sil\u00eancio que cura e transforma. Am\u00e9m.", "practice": "Sente-se em sil\u00eancio. Feche os olhos. Imagine Jesus sentado ao seu lado. Diga-Lhe o que est\u00e1 no seu cora\u00e7\u00e3o. Depois, fique em sil\u00eancio e escute. 10 minutos.", "scripture": "\"Mas tu, quando orares, entra no teu quarto, fecha a porta e ora a teu Pai em segredo; e teu Pai, que v\u00ea em segredo, te recompensar\u00e1.\" \u2014 Mt 6,6", "reflection": "Voc\u00ea j\u00e1 experimentou o sil\u00eancio interior na ora\u00e7\u00e3o? O que acontece quando voc\u00ea tenta ficar em sil\u00eancio diante de Deus?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;